@startuml
enum BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

class Client {
  +nin : string
  +tin : string
  +name : string
  +address : string
}

class BicycleModel {
  +name : string
  +type : BicycleType
  +gears : int
}

class Bicycle {
  +idNumber : string
}

class Store {
  +name : string
  +address : string
}

class Reservation {
  +pickupDate : date
}

class Rental {
  +returnDate : date
}

Client "1..*" -- "0..*" Reservation : makes
BicycleModel "1" -- "0..*" Reservation : requested in
Store "1" -- "0..*" Reservation : pickup location
Reservation "1" -- "0..1" Rental : results in
Bicycle "1" -- "0..1" Rental : is picked up in
Bicycle "0..*" -- "1" BicycleModel : is a model of
Bicycle "0..*" -- "1" Store : belongs to
Store "1" -- "0..*" Bicycle : stores
@enduml

